import bisect


class RangeModule:
    def __init__(self):
        self.ranges = []  # sorted list of disjoint, non-touching (start, end)

    def add_range(self, left, right):
        new_ranges = []
        i = 0
        n = len(self.ranges)
        merged_left, merged_right = left, right

        while i < n and self.ranges[i][1] < left:
            new_ranges.append(self.ranges[i])
            i += 1

        while i < n and self.ranges[i][0] <= right:
            merged_left = min(merged_left, self.ranges[i][0])
            merged_right = max(merged_right, self.ranges[i][1])
            i += 1

        new_ranges.append((merged_left, merged_right))

        while i < n:
            new_ranges.append(self.ranges[i])
            i += 1

        self.ranges = new_ranges

    def query_range(self, left, right):
        idx = bisect.bisect_right(self.ranges, (left, float('inf'))) - 1
        if idx < 0:
            return False
        start, end = self.ranges[idx]
        return start <= left and right <= end

    def remove_range(self, left, right):
        new_ranges = []
        for start, end in self.ranges:
            if end <= left or start >= right:
                new_ranges.append((start, end))
                continue
            if start < left:
                new_ranges.append((start, left))
            if end > right:
                new_ranges.append((right, end))
        self.ranges = new_ranges


def range_module(operations, args):
    module = RangeModule()
    results = []
    for op, arg in zip(operations, args):
        if op == 'add_range':
            module.add_range(arg[0], arg[1])
            results.append(None)
        elif op == 'remove_range':
            module.remove_range(arg[0], arg[1])
            results.append(None)
        elif op == 'query_range':
            results.append(module.query_range(arg[0], arg[1]))
    return results
